// IDB: Right shift on negative signed integer
int x = -100;
// Result depends on whether sign extension is used (IDB)
int y = x >> 2;

// Portable alternative: Use unsigned types for reliable shift
unsigned int ux = (unsigned int)x;
unsigned int uy = ux >> 2; // Always logical shift (zero fill)

// IDB: Character type signedness
// char might be signed or unsigned (IDB)
char c = 200;
// If char is signed 8-bit (max 127), behavior is undefined
// if initialization results in overflow, or IDB if conversion occurs.

// IDB: Size of standard types and structure layout
size_t s_int = sizeof(int);
size_t s_ptr = sizeof(void*);

struct Data { char a; int b; };
// Padding/alignment between 'a' and 'b' is IDB
size_t s_data = sizeof(struct Data);

// Avoid IDB for fixed sizes:
#include <stdint.h>
int32_t guaranteed_int;
